pair A=(0,0), B=(5,0), C=(3/2, 3*sqrt(3)/2);
pair I=incenter(A, B, C), O=circumcenter(A, B, C);
pair D=foot(I, B, C), X=(A+I)/2, F=foot(I, A, B);
pair G=(X+D)/2;
pair G1=z*(G-I)+G;
draw(A--B--C--cycle);
draw(O--G1);
draw(C--G1);
draw(O--A--I);
draw(X--D);
draw(circle(I, r));
label(" $A$ ", A, SW);
label(" $B$ ", B, SE);
label(" $C$ ", C, NE);
label(" $G^{\prime}$ ", G1, N);
label(" $D$ ", D, NE);
label(" $O$ ", O, dir(30));
label(" $I$ ", I, dir(0));
label(" $G$ ", G, W);
label(" $X$ ", X, W);
draw(X--O--D--O--B);
label(" $F$ ", F, S);
draw(I--F);
draw(I--D);
draw(G1--X);
[/asy]
(Note: the diagram makes it look like several untrue things are true; particulary  $O\not\in \overline{XB}, \omega$  in general. Also, like always,  $BC=a,$   $AC=b,$   $AB=c,$   $s=\dfrac{a+b+c}{2},$   $R$  is the circumradius, and  $r$  is the inradius.)

Let  $\omega$  be the incircle of  $\triangle ABC$  which intersects  $BC$  at  $D$  and intersects  $AB$  at  $F,$  let  $X$  be the intersection of  $AI$  and  $\omega,$  let  $G$  be the midpoint of  $DX,$  and let  $G^{\prime}$  be the inversion of  $G$  about  $\omega.$ Observe that  $\angle IAF=30^{\circ},$   $\angle IFA=90^{\circ},$  and  $AF=s-a,$  so  $IF=\dfrac{s-a}{\sqrt{3}}$  and  $AI=2IF.$  Also, since  $X\in \omega,$  we have  $IX=IF,$  so  $AX=AI-IX=IF=\dfrac{s-a}{\sqrt{3}}.$ Claim:  $\overleftrightarrow{OI}$  is the perpendicular bisector of  $DX.$ Proof: Since  $DX$  is a chord of  $\omega,$   $I$  lies on the perpendicular bisector of  $DX,$  so it suffices to show that  $O$  does as well.
Observe that  $\angle BOC=2\angle BAC=120^{\circ},$  so  $\angle OCB=\angle OBC=30^{\circ}.$  Also,  $OB=R$  and  $BD=s-b,$  so by the law of cosines,  $DO^2=OB^2+BD^2-2OB\cdot BD\cos(30^{\circ})=R^2+(s-b)^2-2R(s-b)\cdot \dfrac{\sqrt{3}}{2}=R^2+(s-b)^2-R(s-b)\sqrt{3}.$ Also, recall that  $OI^2=R^2-2Rr,$   $AO=R,$  and  $AX=IX=\dfrac{s-a}{\sqrt{3}},$  so by Apollonius's Theorem on  $\triangle AOI$  with median  $OX,$  we have  $AO^2+OI^2=2R^2-2Rr=2(AX^2+OX^2)=2\cdot \dfrac{(s-a)^2}{3}+2OX^2,$  so  $OX^2=R^2-Rr-\dfrac{(s-a)^2}{3},$  and since  $IF=r=\dfrac{s-a}{\sqrt{3}},$  we have  $OX^2=R^2-R\left(\dfrac{s-a}{\sqrt{3}}\right)-\dfrac{(s-a)^2}{3}.$ By the extended law of sines,  $2R=\dfrac{a}{\sin\angle BAC}=\dfrac{2a}{\sqrt{3}},$  so  $R=\dfrac{a}{\sqrt{3}}.$  Now,  $OX^2=R^2-R\left(\dfrac{s-a}{\sqrt{3}}\right)-\dfrac{(s-a)^2}{3}=R^2-\dfrac{as-a^2}{3}-\dfrac{(s-a)^2}{3}$  and  $DO^2=R^2+(s-b)^2-R(s-b)\sqrt{3}=R^2+(s-b)^2-a(s-b).$ \newpage
Now,\begin{align*} &OX^2=DO^2  &\iff R^2-\dfrac{as-a^2}{3}-\dfrac{(s-a)^2}{3}=R^2+(s-b)^2-a(s-b)  &\iff -\dfrac{as-a^2}{3}-\dfrac{(s-a)^2}{3}=(s-b)^2-a(s-b)  &\iff 0=\dfrac{as-a^2}{3}+\dfrac{(s-a)^2}{3}+(s-b)^2-a(s-b)  &\iff 0=a(s-a)+(s-a)^2+3(s-b)^2-3a(s-b)  &\iff 0=a\left(\dfrac{b+c-a}{2}\right)+\left(\dfrac{b+c-a}{2}\right)^2+3\left(\dfrac{a+c-b}{2}\right)^2-3a\left(\dfrac{a+c-b}{2}\right)  &\iff 0=\dfrac{ab+ac-a^2}{2}+\dfrac{a^2+b^2+c^2+2bc-2ac-2ab}{4}+3\left(\dfrac{a^2+b^2+c^2+2ac-2ab-2bc}{4}\right)-3\left(\dfrac{a^2+ac-ab}{2}\right)  &\iff \dfrac{(ab+ac-a^2)-3(a^2+ac-ab)}{2}+\dfrac{(a^2+b^2+c^2+2bc-2ac-2ab)+3(a^2+b^2+c^2+2ac-2ab-2bc)}{4}  &\iff 0=-2a^2-ac+2ab+(a^2+b^2+c^2)-bc+ac-2ab  &\iff 0=-a^2+b^2+c^2-bc  &\iff a^2=b^2+c^2-2bc\cos(60^{\circ}),  \end{align*}which follows by the law of cosines, so  $OX^2=DO^2,$  so  $OX=DO,$  so  $O$  lies on the perpendicular bisector of  $DX,$  as desired.

Note that  $G$  also lies on the perpendicular bisector of  $DX,$  so  $O,$   $I,$  and  $G$  are collinear, and since  $G^{\prime}\in \overrightarrow{IG},$   $G^{\prime}\in \overleftrightarrow{IO}.$ Also, observe that since  $G^{\prime}$  is the inversion of  $G$  about  $\omega,$  we have  $IG\cdot IG^{\prime}=IX^2,$  so  $\dfrac{IG^{\prime}}{IX}=\dfrac{IX}{IG},$  and since  $\angle G^{\prime}IX=\angle XIG,$  we have  $\triangle G^{\prime}IX\sim \triangle XIG,$  so  $\angle G^{\prime}XI=\angle XGI=90^{\circ},$  and since  $X$  is the midpoint of  $AI,$   $G^{\prime}$  lies on the perpendicular bisector of  $AI.$  Similarly,  $IG\cdot IG^{\prime}=ID^2,$  so  $\dfrac{IG^{\prime}}{ID}=\dfrac{ID}{IG},$  and since  $\angle G^{\prime}ID=\angle DIG,$  we have  $\triangle G^{\prime}ID\sim \triangle DIG.$  As such,  $\angle G^{\prime}DI=\angle DGI=90^{\circ},$  so  $ID\perp G^{\prime}D$  and since  $BC$  is perpendicular to  $ID$  at  $D$  as well, we have  $G^{\prime}\in \overleftrightarrow{BC}.$ Thus,  $G^{\prime}$  lies on  $OI,$   $BC,$  and the perpendicular bisector of  $AI,$  so these three lines are concurrent, as desired.  $\Box$

