```
 import java.util.ArrayList;
public class test {
	static ArrayList<String> c;
	public static void main(String args[])
	{
		c = new ArrayList<String>();
		dfs("",10); //DFS for length n
		System.out.println(c.size());
	}
	public static void dfs(String s,int n)
	{
		String[] arr = {"0","01","10"};
		if(s.length()==n)
			if(!(c.contains(s))) c.add(s);
		if(s.length()<n)
			for(String i: arr) dfs(s+i,n);
	}
}

```

Simple DFS search for arbitrary n length strings.

