\frac{a}{a^2+b^3+c^3} + \frac{b}{a^3+b^2+c^3} + \frac{c}{a^3+b^3+c^2} &= \frac{a^2}{a^3+ab^3+ac^3} + \frac{b^2}{a^3b+b^3+bc^3} + \frac{c^2}{a^3c+b^3c+c^3} 
&\stackrel{\text{Titu}}{\ge} \dfrac{(a+b+c)^2}{a^3+b^3+c^3+ab^3+ac^3+a^3b+bc^3+a^3c+b^3c} 
&= \dfrac{(a+b+c)^2(a^4+b^4+c^4)^2}{(a^4+b^4+c^4+ab^3+ac^3+a^3b+bc^3+a^3c+b^3c)(a^3+b^3+c^3)^2} 
&= \dfrac{(a+b+c)(a^4+b^4+c^4)^2}{(a^3+b^3+c^3)^3} 
&\ge 1
\end{align*}
which follows from Holder, since \[(a+b+c)(a^4+b^4+c^4)(a^4+b^4+c^4) \ge (a^3+b^3+c^3)^3\] as required.  $\square$

