\begin{align*}
    E &= \overline{E}
    \frac{R(\overline{a}AQ-\overline{b}BP)}{Q(\overline{a}AR-\overline{c}CP)} &= \frac{R(aAQ-bBP)}{Q(aAR-cCP)}
    a\overline{a}A^2RQ - \overline{a}cACPQ - a\overline{b}ABPR + \overline{b}cBCP^2 &= a\overline{a}A^2RQ - \overline{a}bABPR -a\overline{c}ACPQ +b\overline{c}BCP^2
    (\overline{a}b-a\overline{b})ABPR + (\overline{a}c-a\overline{c})ACPQ + (\overline{b}c-b\overline{c})BCP^2 &=0
    -ABCPR - ABCPQ -ABCP^2 &=0
    -ABCP(P+Q+R) &=0
\end{align*}
So, it suffices to show that  $P+Q+R=0$  which is quite clear since, 
\begin{align*}
    P+Q+R &= \overline{a}(\overline{c}-\overline{b})+a(b-c) + \overline{b}(\overline{a}-\overline{c})+b(c-a) + \overline{c}(\overline{b}-\overline{a})+c(a-b)
    &= \overline{a}\overline{c} - \overline{a}\overline{c} + \overline{a}\overline{b} -  \overline{a}\overline{b} + \overline{b}\overline{c} - \overline{b}\overline{c} + ab-ab+ac-ac+bc-bc
    &=0
\end{align*}
as desired. So, it is clear that  $\frac{a'-b'}{a'-c'} \in \mathbb{R}$ . Thus, points  $A'$ ,  $B'$  and  $C'$  are collinear which was the required result.

