real r=1/4;
path square=(r,r)--(r,-r)--(-r,-r)--(-r,r)--cycle;
int limit;
for(int i=0;i<=3;i=i+1)
{
if (i==0)
limit=2;
else
limit=3;
for(int j=0;j<=limit;j=j+1)
filldraw(shift(j,i)*square,white);
}
[/asy]

